import{_ as o,o as i,c as a,ag as t}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Docs Site Deployment (docs.rustchat.io)","description":"","frontmatter":{},"headers":[],"relativePath":"operations/docs-site-deployment.md","filePath":"operations/docs-site-deployment.md","lastUpdated":1776687765000}'),s={name:"operations/docs-site-deployment.md"};function l(d,e,r,n,c,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="docs-site-deployment-docs-rustchat-io" tabindex="-1">Docs Site Deployment (<code>docs.rustchat.io</code>) <a class="header-anchor" href="#docs-site-deployment-docs-rustchat-io" aria-label="Permalink to &quot;Docs Site Deployment (\`docs.rustchat.io\`)&quot;">​</a></h1><p>This guide describes how to deploy the documentation site from GitHub to Cloudflare Pages using Cloudflare&#39;s native Git integration.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><ul><li>Source of truth: <code>docs/</code> directory in this repository</li><li>Static site generator: VitePress</li><li>CI quality checks: <code>.github/workflows/docs-ci-cd.yml</code></li><li>Deployment method: Cloudflare Pages Git integration (no GitHub deployment secrets)</li></ul><h2 id="_1-create-a-cloudflare-pages-project" tabindex="-1">1. Create a Cloudflare Pages Project <a class="header-anchor" href="#_1-create-a-cloudflare-pages-project" aria-label="Permalink to &quot;1. Create a Cloudflare Pages Project&quot;">​</a></h2><p>In Cloudflare Dashboard:</p><ol><li>Go to <code>Workers &amp; Pages</code></li><li>Create a new <code>Pages</code> project</li><li>Connect it to your repository for automatic deploys from <code>main</code></li><li>Note the project name (for example <code>rustchat-docs</code>)</li></ol><h2 id="_2-connect-github-repository" tabindex="-1">2. Connect GitHub Repository <a class="header-anchor" href="#_2-connect-github-repository" aria-label="Permalink to &quot;2. Connect GitHub Repository&quot;">​</a></h2><p>In the Pages project:</p><ol><li>Open <code>Settings</code> -&gt; <code>Build &amp; deployments</code></li><li>Connect the <code>kubedoio/rustchat</code> repository</li><li>Configure build: <ul><li>Root directory: <code>docs</code></li><li>Build command: <code>npm ci --ignore-scripts &amp;&amp; npm run docs:build</code></li><li>Build output directory: <code>.vitepress/dist</code></li><li>Deploy command (if required by your Cloudflare mode): <code>npx wrangler versions upload</code></li></ul></li></ol><p>The repository includes <code>docs/wrangler.jsonc</code> so <code>wrangler versions upload</code> can resolve:</p><ul><li>Worker name (<code>docs-rustchat-io</code>)</li><li>Compatibility date</li><li>Assets directory (<code>.vitepress/dist</code>)</li></ul><h2 id="_3-workflow-behavior" tabindex="-1">3. Workflow Behavior <a class="header-anchor" href="#_3-workflow-behavior" aria-label="Permalink to &quot;3. Workflow Behavior&quot;">​</a></h2><ul><li>On pull requests: runs docs link checks and builds the VitePress site.</li><li>On push to <code>main</code>: Cloudflare Pages deploys from the connected repository.</li><li>GitHub Actions stays as an independent quality gate.</li></ul><h2 id="_4-configure-custom-domain" tabindex="-1">4. Configure Custom Domain <a class="header-anchor" href="#_4-configure-custom-domain" aria-label="Permalink to &quot;4. Configure Custom Domain&quot;">​</a></h2><p>In the Pages project:</p><ol><li>Open <code>Custom domains</code></li><li>Add <code>docs.rustchat.io</code></li><li>Complete DNS validation if required</li></ol><p>Cloudflare manages TLS automatically once the domain is attached.</p><h2 id="_5-manual-validation" tabindex="-1">5. Manual Validation <a class="header-anchor" href="#_5-manual-validation" aria-label="Permalink to &quot;5. Manual Validation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check-links</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>If CI succeeds and Cloudflare Git integration is active, <code>docs.rustchat.io</code> updates automatically after merge to <code>main</code>.</p>`,21)])])}const m=o(s,[["render",l]]);export{u as __pageData,m as default};
